def binary_search(nums, target):
    low, high = 0, len(nums) - 1
    while low <= high:              # <= so a 1-item range is still checked
        mid = (low + high) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

