# "Find the first repeated item."
# Pattern: have I seen this before? -> a set
def first_repeat(items):
    seen = set()
    for item in items:
        if item in seen:
            return item
        seen.add(item)
    return None

print(first_repeat([3, 1, 3, 2]))  # O(n) time, O(n) space
